type SiTableSearchMode = 'description' | 'code' | 'both';
type SiTableFilterOperator = 'contains' | 'equals' | 'not_equals' | 'empty' | 'not_empty';

function siSanitizeTableFileName(name: string) {
  const trimmed = name.trim() || 'layer';
  const cleaned = trimmed.replace(/[<>:"/\\|?*\x00-\x1F]/g, '_').replace(/\s+/g, ' ');
  return cleaned.length > 80 ? cleaned.slice(0, 80).trim() : cleaned;
}

/** Attribute table row key — same stable ID as map canvas (OBJECT_ID / Feature_ID, never row order). */
function siComputeFeatureRowKey(feature: any, idx: number, cache: Map<object, string>): string {
  if (feature && typeof feature === 'object') {
    const cached = cache.get(feature);
    if (cached) return cached;
  }
  const key = computeStableGisFeatureKey(feature, idx);
  if (feature && typeof feature === 'object') cache.set(feature, key);
  return key;
}

function siFindTableRowKeyForFeatureKey(
  features: any[],
  featureKey: string,
  cache: Map<object, string>,
): string | null {
  for (let i = 0; i < features.length; i++) {
    const ft = features[i];
    if (computeStableGisFeatureKey(ft, i) !== featureKey) continue;
    return siComputeFeatureRowKey(ft, i, cache);
  }
  return null;
}

function siScrollAttributeTableRowIntoView(rowKey: string) {
  if (!rowKey) return;
  requestAnimationFrame(() => {
    const esc =
      typeof CSS !== 'undefined' && 'escape' in CSS ? CSS.escape(rowKey) : rowKey.replace(/"/g, '\\"');
    document.querySelector(`tr[data-row-key="${esc}"]`)?.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
  });
}

function siBuildTableSelectionHighlightFeatures(
  features: any[],
  selectedKeys: Set<string>,
  cache: Map<object, string>,
): Array<{ type: 'Feature'; geometry: unknown; properties: Record<string, unknown> }> {
  const out: Array<{ type: 'Feature'; geometry: unknown; properties: Record<string, unknown> }> = [];
  for (let idx = 0; idx < features.length; idx++) {
    const ft = features[idx];
    if (!selectedKeys.has(siComputeFeatureRowKey(ft, idx, cache))) continue;
    const geometry = ft?.geometry;
    if (!geometry || typeof geometry !== 'object') continue;
    out.push({
      type: 'Feature',
      geometry,
      properties: {
        _siTableSel: true,
        ...(ft?.properties && typeof ft.properties === 'object' ? ft.properties : {}),
      },
    });
  }
  return out;
}

function migrateStoredSymbology(raw: unknown): SymbologyConfig | undefined {
  if (!raw || typeof raw !== 'object') return undefined;
  const o = raw as Record<string, unknown>;
  const cr = o.colorRamp;
  let colorRamp: SymbologyColorRamp | undefined;
  if (cr === 'green') colorRamp = 'greens';
  else if (cr === 'warm') colorRamp = 'magma';
  else if (cr === 'viridis' || cr === 'blues' || cr === 'greens' || cr === 'plasma' || cr === 'magma' || cr === 'turbo') {
    colorRamp = cr;
  }
  let style = o.style;
  // Keep 'single' as Single symbol (legacy code used to remap it to graduated 'color').
  if (style === 'classified') style = 'unique';
  if (style === 'simple') style = 'single';
  let method = o.method;
  if (method === 'natural-breaks') method = 'jenks';
  if (method === 'equal-interval') method = 'equal_interval';
  const out: SymbologyConfig = {};
  if (typeof o.useArcGisOnline === 'boolean') out.useArcGisOnline = o.useArcGisOnline;
  if (typeof style === 'string') out.style = style as SymbologyStyle;
  if (typeof o.field === 'string') out.field = o.field;
  if (typeof o.classes === 'number') out.classes = o.classes;
  if (typeof method === 'string') out.method = method as SymbologyClassMethod;
  if (colorRamp) out.colorRamp = colorRamp;
  if (typeof o.threshold === 'number') out.threshold = o.threshold;
  if (o.classOverrides && typeof o.classOverrides === 'object') {
    out.classOverrides = o.classOverrides as SymbologyConfig['classOverrides'];
  }
  if (Array.isArray(o.breakOverrides)) {
    out.breakOverrides = o.breakOverrides as SymbologyConfig['breakOverrides'];
  }
  return Object.keys(out).length ? out : undefined;
}

function parseStoredCustomLayers(raw: string | null): CustomLayer[] {
  if (!raw || typeof raw !== 'string') return [];
  try {
    const data = JSON.parse(raw);
    if (!Array.isArray(data)) return [];
    return data
      .filter(
        (x: unknown) =>
          x &&
          typeof x === 'object' &&
          typeof (x as CustomLayer).id === 'string' &&
          typeof (x as CustomLayer).name === 'string' &&
          typeof (x as CustomLayer).visible === 'boolean' &&
          (((x as CustomLayer).geojson && typeof (x as CustomLayer).geojson === 'object') ||
            ((x as CustomLayer).source === 'arcgis' &&
              typeof (x as CustomLayer).sourceUrl === 'string' &&
              !!(x as CustomLayer).sourceUrl?.trim())),
      )
      .map((x: any) => {
        const migratedSym = migrateStoredSymbology(x.symbology);
        let symbology = migratedSym;
        const portalId =
          typeof x.sourceUrl === 'string' ? parseGisContentPortalLayerUrl(x.sourceUrl) : null;
        const portalRow = portalId ? getGisContentRowById(portalId) : null;
        const portalArcgisUrl = portalRow ? resolveHostedFeatureLayerExternalUrl(portalRow) : null;
        const hasArcgisRestSource =
          x.source === 'arcgis' ||
          Boolean(portalArcgisUrl) ||
          (typeof x.sourceUrl === 'string' &&
            /\/(FeatureServer|MapServer)\/\d+\/?$/i.test(x.sourceUrl.trim()));
        let useArcGisSymbologyResolved =
          typeof x.useArcGisSymbology === 'boolean'
            ? x.useArcGisSymbology
            : hasArcgisRestSource
              ? true
              : undefined;
        if (
          hasArcgisRestSource &&
          useArcGisSymbologyResolved !== false &&
          symbology?.useArcGisOnline !== false
        ) {
          symbology = { ...(symbology ?? {}), useArcGisOnline: true };
        } else if (
          x.source === 'arcgis' &&
          useArcGisSymbologyResolved !== false &&
          symbology?.useArcGisOnline !== false
        ) {
          symbology = { ...(symbology ?? {}), useArcGisOnline: true };
        } else if (
          typeof symbology?.useArcGisOnline !== 'boolean' &&
          (x.source === 'arcgis' ||
            (x.arcgisDrawingInfo && typeof x.arcgisDrawingInfo === 'object') ||
            (x.arcgisLayerDefinition && typeof x.arcgisLayerDefinition === 'object') ||
            (typeof x.sourceUrl === 'string' && x.sourceUrl.trim()))
        ) {
          const fallbackOnline = useArcGisSymbologyResolved !== false;
          symbology = { ...(symbology ?? {}), useArcGisOnline: fallbackOnline };
        }
        const sanitizedDrawingInfo =
          x.arcgisDrawingInfo && typeof x.arcgisDrawingInfo === 'object'
            ? (sanitizeArcgisDrawingInfoForClient(x.arcgisDrawingInfo) as Record<string, unknown> | null) ?? undefined
            : undefined;
        const sanitizedServiceDi =
          x.arcgisDrawingInfoService && typeof x.arcgisDrawingInfoService === 'object'
            ? (sanitizeArcgisDrawingInfoForClient(x.arcgisDrawingInfoService) as Record<string, unknown> | null) ??
              undefined
            : undefined;
        const wantsOnline = symbology?.useArcGisOnline === true;
        return {
          id: String(x.id),
          name: String(x.name),
          geojson:
            x.geojson && typeof x.geojson === 'object'
              ? x.geojson
              : x.source === 'arcgis'
                ? createEmptyArcGisFeatureCollection()
                : undefined,
          visible: Boolean(x.visible),
          color: typeof x.color === 'string' ? x.color : undefined,
          source: x.source === 'arcgis' || x.source === 'upload' || x.source === 'api' || x.source === 'stac' ? x.source : undefined,
          sourceUrl: typeof x.sourceUrl === 'string' ? x.sourceUrl : undefined,
          authToken: typeof x.authToken === 'string' ? x.authToken : undefined,
          arcgisDrawingInfo: wantsOnline ? undefined : sanitizedDrawingInfo,
          arcgisDrawingInfoService: wantsOnline ? undefined : sanitizedServiceDi,
          useArcGisSymbology: useArcGisSymbologyResolved,
          arcgisLayerDefinition:
            x.arcgisLayerDefinition && typeof x.arcgisLayerDefinition === 'object'
              ? (x.arcgisLayerDefinition as ArcgisLayerDefLite)
              : undefined,
          symbology,
          renderMode: x.renderMode === 'raster' || x.renderMode === 'vector' ? x.renderMode : undefined,
          raster:
            x.raster && typeof x.raster === 'object' && typeof x.raster.url === 'string' && Array.isArray(x.raster.coordinates)
              ? (x.raster as CustomLayer['raster'])
              : undefined,
          ephemeral: typeof x.ephemeral === 'boolean' ? x.ephemeral : undefined,
          importMetadata: x.importMetadata && typeof x.importMetadata === 'object' ? x.importMetadata : undefined,
          bimBlobUrl: typeof x.bimBlobUrl === 'string' ? x.bimBlobUrl : undefined,
          popupConfig: x.popupConfig ? normalizeSiLayerPopupConfig(x.popupConfig) : undefined,
          mapOpacity:
            typeof x.mapOpacity === 'number' &&
            Number.isFinite(x.mapOpacity) &&
            x.mapOpacity >= 0.05 &&
            x.mapOpacity <= 1
              ? x.mapOpacity
              : undefined,
          labelFieldName: typeof x.labelFieldName === 'string' && x.labelFieldName.trim() ? x.labelFieldName : undefined,
          labelStyle: x.labelStyle
            ? normalizeSiLayerLabelStyle({
                ...DEFAULT_SI_LAYER_LABEL_STYLE,
                ...(typeof x.labelStyle === 'object' ? x.labelStyle : {}),
                fieldName:
                  (typeof x.labelFieldName === 'string' && x.labelFieldName.trim()
                    ? x.labelFieldName
                    : typeof (x.labelStyle as { fieldName?: unknown })?.fieldName === 'string'
                      ? String((x.labelStyle as { fieldName?: unknown }).fieldName)
                      : '') || '',
              })
            : undefined,
          definitionQueryText:
            typeof x.definitionQueryText === 'string' && x.definitionQueryText.trim() ? x.definitionQueryText : undefined,
          definitionFilter:
            typeof x.definitionQueryText === 'string' && x.definitionQueryText.trim()
              ? siCompileDefinitionQuery(x.definitionQueryText) ?? undefined
              : undefined,
          fillColor: typeof x.fillColor === 'string' ? x.fillColor : undefined,
          weight: typeof x.weight === 'number' && Number.isFinite(x.weight) ? x.weight : undefined,
          strokeStyle:
            x.strokeStyle === 'solid' || x.strokeStyle === 'dashed' || x.strokeStyle === 'dotted' || x.strokeStyle === 'dashdot'
              ? x.strokeStyle
              : undefined,
          polygonFillAlpha:
            typeof x.polygonFillAlpha === 'number' && Number.isFinite(x.polygonFillAlpha) && x.polygonFillAlpha >= 0 && x.polygonFillAlpha <= 1
              ? x.polygonFillAlpha
              : undefined,
          pointRadius:
            typeof x.pointRadius === 'number' && Number.isFinite(x.pointRadius) ? x.pointRadius : undefined,
          fillStyle:
            x.fillStyle === 'solid' || x.fillStyle === 'pattern' || x.fillStyle === 'hatch' || x.fillStyle === 'gradient'
              ? x.fillStyle
              : undefined,
          blendMode:
            x.blendMode === 'multiply' ||
            x.blendMode === 'screen' ||
            x.blendMode === 'overlay' ||
            x.blendMode === 'darken' ||
            x.blendMode === 'lighten' ||
            x.blendMode === 'normal'
              ? x.blendMode
              : undefined,
          arcgisServiceType: (() => {
            if (
              x.arcgisServiceType === 'feature' ||
              x.arcgisServiceType === 'map' ||
              x.arcgisServiceType === 'vector-tile' ||
              x.arcgisServiceType === 'image'
            ) {
              return x.arcgisServiceType
            }
            if (x.source === 'arcgis' && typeof x.sourceUrl === 'string') {
              const detected = detectArcGisServiceTypeFromUrl(x.sourceUrl)
              return detected !== 'unknown' ? detected : ('feature' as const)
            }
            return undefined
          })(),
          viewportStreaming:
            typeof x.viewportStreaming === 'boolean'
              ? x.viewportStreaming
              : x.source === 'arcgis' &&
                  typeof x.sourceUrl === 'string' &&
                  isAgroStructuresLayerUrl(x.sourceUrl)
                ? true
                : undefined,
          arcgisRasterTiles:
            x.arcgisRasterTiles &&
            typeof x.arcgisRasterTiles === 'object' &&
            Array.isArray(x.arcgisRasterTiles.tiles)
              ? (x.arcgisRasterTiles as ArcGisRasterTilesConfig)
              : undefined,
          arcgisVectorTiles:
            x.arcgisVectorTiles &&
            typeof x.arcgisVectorTiles === 'object' &&
            Array.isArray(x.arcgisVectorTiles.tiles)
              ? (x.arcgisVectorTiles as ArcGisVectorTilesConfig)
              : undefined,
        };
      });
  } catch {
    return [];
  }
}

function siBimAnchorFootprint(lng: number, lat: number, halfEdgeM = 140): any {
  const cos = Math.max(1e-6, Math.cos((lat * Math.PI) / 180));
  const dLat = halfEdgeM / 111_320;
  const dLng = halfEdgeM / (111_320 * cos);
  const w = lng - dLng;
  const e = lng + dLng;
  const s = lat - dLat;
  const n = lat + dLat;
  return {
    type: 'FeatureCollection',
    features: [
      {
        type: 'Feature',
        properties: {
          kind: 'bim_anchor',
          note:
            'IFC model uploaded. Full 3D geometry needs a BIM viewer; this footprint anchors the file to the current map view.',
        },
        geometry: {
          type: 'Polygon',
          coordinates: [
            [
              [w, s],
              [e, s],
              [e, n],
              [w, n],
              [w, s],
            ],
          ],
        },
      },
    ],
  };
}

function siRasterExtentFootprint(coords: RasterMapCoordinates): any {
  const lngs = coords.map(c => c[0]);
  const lats = coords.map(c => c[1]);
  const w = Math.min(...lngs);
  const e = Math.max(...lngs);
  const s = Math.min(...lats);
  const n = Math.max(...lats);
  return {
    type: 'FeatureCollection',
    features: [
      {
        type: 'Feature',
        properties: { kind: 'raster_extent' },
        geometry: {
          type: 'Polygon',
          coordinates: [
            [
              [w, s],
              [e, s],
              [e, n],
              [w, n],
              [w, s],
            ],
          ],
        },
      },
    ],
  };
}

const SI_MAPBOX_POLY_FILTER: any = ['in', ['geometry-type'], ['literal', ['Polygon', 'MultiPolygon']]];
const SI_MAPBOX_LINE_ONLY_FILTER: any = ['in', ['geometry-type'], ['literal', ['LineString', 'MultiLineString']]];
const SI_MAPBOX_LINE_POLY_FILTER: any = [
  'in',
  ['geometry-type'],
  ['literal', ['Polygon', 'MultiPolygon', 'LineString', 'MultiLineString']],
];
const SI_MAPBOX_POINT_FILTER: any = ['in', ['geometry-type'], ['literal', ['Point', 'MultiPoint']]];

/** Mapbox GL source/layer ids must be alphanumeric + _ - (portal ids may contain other chars). */
const siSafeMapboxLayerId = (value: unknown) =>
  String(value ?? 'layer').replace(/[^A-Za-z0-9_-]/g, '_').slice(0, 80);

function siMapboxZoomScaledLinePaint(linePaint: Record<string, unknown>, op: number): Record<string, unknown> {
  const rawW = linePaint['line-width'];
  const baseLw =
    typeof rawW === 'number' && Number.isFinite(rawW) ? rawW : SI_DEFAULT_VECTOR_LINE_WEIGHT;
  const out: Record<string, unknown> = {
    ...linePaint,
    'line-opacity': linePaint['line-opacity'] ?? op * 0.92,
  };
  if (typeof rawW === 'number' || rawW === undefined) {
    out['line-width'] = [
      'interpolate',
      ['linear'],
      ['zoom'],
      2,
      baseLw * 0.35,
      10,
      baseLw * 0.85,
      16,
      baseLw * 1.25,
    ];
  }
  return out;
}

/** Default vector look for GIS Content / portal layers — outline only (ArcGIS Pro hollow). */
const SI_PORTAL_LAYER_VISIBLE_OUTLINE = '#000000';
const SI_PORTAL_LAYER_VISIBLE_FILL_ALPHA = 0;

function siDefaultPortalVectorLayerFields() {
  return {
    ...siDefaultNewVectorLayerFields(),
    color: SI_PORTAL_LAYER_VISIBLE_OUTLINE,
    fillColor: SI_PORTAL_LAYER_VISIBLE_OUTLINE,
    weight: SI_DEFAULT_VECTOR_LINE_WEIGHT,
    polygonFillAlpha: SI_PORTAL_LAYER_VISIBLE_FILL_ALPHA,
  };
}

type SiMapboxCanvasLike = {
  getSource(id: string): unknown;
  getLayer(id: string): unknown;
  addSource(id: string, spec: object): void;
  addLayer(spec: object, beforeId?: string): void;
  removeLayer(id: string): void;
  removeSource(id: string): void;
  moveLayer?(id: string, beforeId?: string): void;
  setPaintProperty?(layerId: string, name: string, value: unknown): void;
  setLayoutProperty?(layerId: string, name: string, value: unknown): void;
  setFilter?(layerId: string, filter: unknown): void;
  getStyle(): { layers?: Array<{ id: string; type?: string }> };
  triggerRepaint?(): void;
  hasImage?(id: string): boolean;
  loadImage?(url: string, callback: (error?: Error, image?: HTMLImageElement | ImageBitmap) => void): void;
  addImage?(id: string, image: unknown, options?: { pixelRatio?: number }): void;
};

/**
 * Register (once) a luxurious blue water-drop marker icon in the map sprite so
 * point layers (e.g. Recommended Wells) can render as water points instead of
 * flat circles. Returns true when the image is available for use.
 */
function siEnsureWaterDropImage(map: SiMapboxCanvasLike, id: 'si-water-drop' = 'si-water-drop'): boolean {
  try {
    if (typeof map.hasImage === 'function' && map.hasImage(id)) return true;
    if (typeof map.addImage !== 'function' || typeof document === 'undefined') return false;
    const ratio = 2;
    const W = 30;
    const H = 40;
    const canvas = document.createElement('canvas');
    canvas.width = W * ratio;
    canvas.height = H * ratio;
    const ctx = canvas.getContext('2d');
    if (!ctx) return false;
    ctx.scale(ratio, ratio);

    const cx = W / 2;
    const cy = 15;
    const r = 11;
    const tipY = H - 2.5;

    // Teardrop silhouette: top circle blended into a pointed tip.
    ctx.beginPath();
    ctx.moveTo(cx, tipY);
    ctx.quadraticCurveTo(cx - r, cy + (tipY - cy) * 0.34, cx - r, cy);
    ctx.arc(cx, cy, r, Math.PI, 0, true);
    ctx.quadraticCurveTo(cx + r, cy + (tipY - cy) * 0.34, cx, tipY);
    ctx.closePath();

    const grad = ctx.createLinearGradient(0, cy - r, 0, tipY);
    grad.addColorStop(0, '#7dd3fc');
    grad.addColorStop(0.5, '#38bdf8');
    grad.addColorStop(1, '#0284c7');
    ctx.shadowColor = 'rgba(2, 23, 51, 0.45)';
    ctx.shadowBlur = 3;
    ctx.shadowOffsetY = 1.5;
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.shadowColor = 'transparent';
    ctx.shadowBlur = 0;
    ctx.lineWidth = 1.6;
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.92)';
    ctx.stroke();

    // Glossy highlight.
    ctx.beginPath();
    ctx.ellipse(cx - 3.2, cy - 2.6, 3.1, 4.4, -0.5, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(255, 255, 255, 0.55)';
    ctx.fill();

    const img = ctx.getImageData(0, 0, canvas.width, canvas.height);
    map.addImage(id, img, { pixelRatio: ratio });
    return typeof map.hasImage === 'function' ? map.hasImage(id) : true;
  } catch {
    return false;
  }
}

function siEnsureArcgisPointIconImages(
  map: SiMapboxCanvasLike,
  spec: ArcgisPointIconLayerSpec,
  onReady: () => void,
): boolean {
  const entries = spec.entries;
  if (!entries.length) return false;
  let pending = 0;
  for (const entry of entries) {
    try {
      if (typeof map.hasImage === 'function' && map.hasImage(entry.imageId)) continue;
    } catch {
      /* ignore */
    }
    pending += 1;
    const done = () => {
      pending -= 1;
      if (pending <= 0) onReady();
    };
    if (entry.imageUrl.startsWith('data:') && typeof document !== 'undefined') {
      const img = new Image();
      img.onload = () => {
        try {
          if (typeof map.hasImage === 'function' && map.hasImage(entry.imageId)) {
            done();
            return;
          }
          map.addImage?.(entry.imageId, img, { pixelRatio: 2 });
        } catch (err) {
          console.error('[si-point-symbol] Failed to register data-url icon', entry.imageId, err);
        }
        done();
      };
      img.onerror = () => {
        console.error('[si-point-symbol] Failed to load data-url icon', entry.imageId);
        done();
      };
      img.src = entry.imageUrl;
      continue;
    }
    if (typeof map.loadImage === 'function') {
      map.loadImage(entry.imageUrl, (err, image) => {
        if (err || !image) {
          console.error('[si-point-symbol] Failed to load icon url', entry.imageUrl, err);
          done();
          return;
        }
        try {
          if (typeof map.hasImage === 'function' && map.hasImage(entry.imageId)) {
            done();
            return;
          }
          map.addImage?.(entry.imageId, image);
        } catch (addErr) {
          console.error('[si-point-symbol] Failed to add icon image', entry.imageId, addErr);
        }
        done();
      });
    } else {
      done();
    }
  }
  return pending === 0;
}

const SI_MAPBOX_CUSTOM_LAYER_SUFFIXES = ['-fill', '-line', '-circle', '-marker', '-arcgis-icon', '-cluster', '-cluster-count', '-raster', '-arcgis-raster', '-label'] as const;

/**
 * Compile a simple `field op value` definition query into a Mapbox filter expression.
 * Supported operators: `=`, `==`, `!=`, `>`, `>=`, `<`, `<=`, `~` (case-insensitive contains).
 * `fieldNames` (optional) is used to resolve the field name case-insensitively. Returns
 * `null` when the text cannot be parsed.
 */
function siCompileDefinitionQuery(text: string, fieldNames?: string[]): unknown[] | null {
  const raw = String(text || '').trim();
  if (!raw) return null;
  const m = raw.match(/^\s*([^<>=!~]+?)\s*(>=|<=|!=|==|=|>|<|~)\s*(.+?)\s*$/);
  if (!m) return null;
  let field = m[1].trim().replace(/^["'\[]+|["'\]]+$/g, '').trim();
  const op = m[2];
  let valueRaw = m[3].trim().replace(/^["']|["']$/g, '');
  if (!field) return null;
  if (Array.isArray(fieldNames) && fieldNames.length) {
    const hit = fieldNames.find(f => f.toLowerCase() === field.toLowerCase());
    if (hit) field = hit;
  }
  const num = Number(valueRaw);
  const isNum = valueRaw !== '' && Number.isFinite(num);
  const getStr = ['to-string', ['get', field]];
  const getNum = ['to-number', ['get', field]];
  switch (op) {
    case '~':
      return ['!=', ['index-of', valueRaw.toLowerCase(), ['downcase', getStr]], -1];
    case '!=':
      return isNum ? ['!=', getNum, num] : ['!=', getStr, valueRaw];
    case '=':
    case '==':
      return isNum ? ['==', getNum, num] : ['==', getStr, valueRaw];
    case '>':
      return isNum ? ['>', getNum, num] : ['>', getStr, valueRaw];
    case '>=':
      return isNum ? ['>=', getNum, num] : ['>=', getStr, valueRaw];
    case '<':
      return isNum ? ['<', getNum, num] : ['<', getStr, valueRaw];
    case '<=':
      return isNum ? ['<=', getNum, num] : ['<=', getStr, valueRaw];
    default:
      return null;
  }
}

function siRemoveMapboxCustomLayerStack(map: SiMapboxCanvasLike, sourceId: string) {
  for (const suffix of SI_MAPBOX_CUSTOM_LAYER_SUFFIXES) {
    const lid = `${sourceId}${suffix}`;
    try {
      if (map.getLayer(lid)) map.removeLayer(lid);
    } catch {
      /* ignore */
    }
  }
  try {
    const style = map.getStyle();
    const vtLayerIds = (style.layers ?? [])
      .map(l => l.id)
      .filter(id => id.startsWith(`${sourceId}-vt-`));
    for (const lid of vtLayerIds) {
      try {
        if (map.getLayer(lid)) map.removeLayer(lid);
      } catch {
        /* ignore */
      }
    }
  } catch {
    /* ignore */
  }
  try {
    if (map.getSource(sourceId)) map.removeSource(sourceId);
  } catch {
    /* ignore */
  }
}

/**
 * Show/hide every sub-layer (fill, line, circle, cluster, raster, label...) of a custom layer
 * via the Mapbox `visibility` layout property. Toggling visibility â€” instead of removing and
 * re-adding the layer stack â€” is instant, keeps all geometry types in sync, and preserves the
 * exact draw order (z-index) when a layer is switched back on (QGIS/ArcGIS-style behaviour).
 */
function siSetMapboxCustomLayerStackVisibility(
  map: SiMapboxCanvasLike,
  sourceId: string,
  visible: boolean,
) {
  if (typeof map.setLayoutProperty !== 'function') return;
  const value = visible ? 'visible' : 'none';
  for (const suffix of SI_MAPBOX_CUSTOM_LAYER_SUFFIXES) {
    const lid = `${sourceId}${suffix}`;
    if (!map.getLayer(lid)) continue;
    try {
      map.setLayoutProperty(lid, 'visibility', value);
    } catch {
      /* ignore */
    }
  }
}

/**
 * Floating, portal-positioned layer-options menu (ArcGIS / layer-tree style). The ...
 * trigger lives inline in the layer row, but the menu is rendered to document.body and
 * positioned via the trigger's bounding box so it never gets clipped by the compact
 * panel's overflow and always floats cleanly above the dock.
 */
type SiLayerMenuExportFormat = Extract<VectorExportFormat, 'shp' | 'kml' | 'geojson' | 'csv'>;

const SI_LAYER_EXPORT_FORMATS: Array<{
  id: SiLayerMenuExportFormat;
  label: string;
  icon: string;
  hint: string;
}> = [
  { id: 'shp', label: 'Shp', icon: 'fa-solid fa-file-zipper', hint: 'Esri Shapefile ZIP (.shp/.shx/.dbf/.prj)' },
  { id: 'kml', label: 'KML', icon: 'fa-solid fa-globe', hint: 'Google Earth KML (.kml)' },
  { id: 'geojson', label: 'GeoJSON', icon: 'fa-solid fa-code', hint: 'GeoJSON FeatureCollection (.geojson)' },
  { id: 'csv', label: 'CSV', icon: 'fa-solid fa-file-csv', hint: 'Attribute table with lon/lat (.csv)' },
];

function SiLayerExportMenuGroup({
  disabled,
  disabledHint,
  onPick,
}: {
  disabled?: boolean;
  disabledHint?: string;
  onPick: (format: SiLayerMenuExportFormat) => void;
}) {
  const [open, setOpen] = useState(false);
  return (
    <div className={'si-env-layer-options-menu__export' + (open ? ' is-open' : '')}>
      <button
        type="button"
        role="menuitem"
        className={
          'si-env-layer-options-menu__item si-env-layer-options-menu__item--export' +
          (disabled ? ' si-env-layer-options-menu__item--disabled' : '')
        }
        aria-haspopup="true"
        aria-expanded={open}
        disabled={disabled}
        title={disabled ? disabledHint : 'Export layer as Shp, KML, GeoJSON, or CSV'}
        onClick={e => {
          e.stopPropagation();
          if (!disabled) setOpen(v => !v);
        }}
      >
        <i className="fa-solid fa-file-export" aria-hidden />
        <span>Export</span>
        <i
          className={`fa-solid fa-chevron-${open ? 'up' : 'down'} si-env-layer-options-menu__export-chevron`}
          aria-hidden
        />
      </button>
      {open && !disabled ? (
        <div className="si-env-layer-options-menu__export-list" role="group" aria-label="Export format">
          {SI_LAYER_EXPORT_FORMATS.map(fmt => (
            <button
              key={fmt.id}
              type="button"
              role="menuitem"
              className="si-env-layer-options-menu__item si-env-layer-options-menu__item--export-fmt"
              title={fmt.hint}
              onClick={e => {
                e.stopPropagation();
                onPick(fmt.id);
              }}
            >
              <i className={fmt.icon} aria-hidden />
              <span>{fmt.label}</span>
            </button>
          ))}
        </div>
      ) : null}
    </div>
  );
}

function SiLayerOptionsMenuPortal({
  open,
  layerLabel,
  onToggleOpen,
  children,
}: {
  open: boolean;
  layerLabel: string;
  onToggleOpen: () => void;
  children: ReactNode;
}) {
  const btnRef = useRef<HTMLButtonElement | null>(null);
  const popRef = useRef<HTMLDivElement | null>(null);
  const [coords, setCoords] = useState<{ top: number; left: number; maxHeight: number } | null>(null);

  const place = useCallback(() => {
    const btn = btnRef.current;
    if (!btn) return;
    const r = btn.getBoundingClientRect();
    const width = 224;
    const margin = 8;
    const gap = 6;
    // Measure the real menu height when available so tall menus are positioned
    // (and clamped) to stay fully on screen — never clipped by the viewport edge.
    const measured = popRef.current?.scrollHeight ?? 0;
    const estHeight = Math.min(Math.max(measured || 380, 220), window.innerHeight - margin * 2);
    let left = r.right - width;
    if (left < margin) left = margin;
    if (left + width > window.innerWidth - margin) left = window.innerWidth - margin - width;

    const spaceBelow = window.innerHeight - r.bottom - gap - margin;
    const spaceAbove = r.top - gap - margin;
    let top: number;
    let maxHeight: number;
    if (estHeight <= spaceBelow || spaceBelow >= spaceAbove) {
      // Open downward (preferred when it fits or there's more room below).
      top = r.bottom + gap;
      maxHeight = Math.max(160, Math.min(estHeight, spaceBelow));
    } else {
      // Flip above the trigger and clamp to the room available there.
      maxHeight = Math.max(160, Math.min(estHeight, spaceAbove));
      top = Math.max(margin, r.top - gap - maxHeight);
    }
    setCoords({ top, left, maxHeight });
  }, []);

  useLayoutEffect(() => {
    if (open) place();
    else setCoords(null);
  }, [open, place]);

  useLayoutEffect(() => {
    if (!open) return;
    const el = popRef.current;
    if (!el || typeof ResizeObserver === 'undefined') return;
    const ro = new ResizeObserver(() => place());
    ro.observe(el);
    return () => ro.disconnect();
  }, [open, place]);

  useEffect(() => {
    if (!open) return;
    const onReflow = () => place();
    window.addEventListener('resize', onReflow);
    window.addEventListener('scroll', onReflow, true);
    return () => {
      window.removeEventListener('resize', onReflow);
      window.removeEventListener('scroll', onReflow, true);
    };
  }, [open, place]);

  return (
    <>
      <button
        ref={btnRef}
        type="button"
        className={'si-env-layer-action-btn si-env-layer-action-btn--menu' + (open ? ' is-active' : '')}
        title="Layer options (zoom, table, symbology, pop-ups, opacity, order...)"
        aria-label={`Layer options for ${layerLabel}`}
        aria-haspopup="menu"
        aria-expanded={open}
        onClick={e => {
          e.stopPropagation();
          onToggleOpen();
        }}
      >
        <i className="fa-solid fa-ellipsis" aria-hidden />
      </button>
      {open
        ? createPortal(
            <div
              ref={popRef}
              className="si-env-layer-options-menu si-env-layer-options-menu--floating"
              role="menu"
              style={{
                position: 'fixed',
                top: coords ? coords.top : -9999,
                left: coords ? coords.left : -9999,
                maxHeight: coords ? coords.maxHeight : undefined,
                visibility: coords ? 'visible' : 'hidden',
              }}
              onMouseDown={e => e.stopPropagation()}
              onClick={e => e.stopPropagation()}
            >
              {children}
            </div>,
            document.body,
          )
        : null}
    </>
  );
}

function siMapboxInsertBeforeId(map: SiMapboxCanvasLike): string | undefined {
  try {
    const layers = map.getStyle()?.layers;
    if (!Array.isArray(layers) || !layers.length) return undefined;
    // Pure SI raster scaffold has no label/symbol layers — returning undefined appends overlays on top.
    const hasOnlyBasemapRasters = layers.every(
      (l: { id?: string; type?: string }) =>
        !l?.id ||
        l.type === 'background' ||
        l.id.startsWith(SI_BASE_LAYER_PREFIX) ||
        l.id.startsWith(SI_BASE_SOURCE_PREFIX) ||
        l.id === 'topo-base-layer' ||
        l.id === 'sat3d-base-layer' ||
        l.id === 'google-earth-sat-layer' ||
        l.id.startsWith('topo-fallback-layer-') ||
        // ignore already-mounted custom overlays when measuring style shape
        SI_MAPBOX_CUSTOM_LAYER_SUFFIXES.some(sfx => l.id!.endsWith(sfx)) ||
        l.id.includes('-vt-') ||
        l.id.includes('-arcgis-'),
    );
    if (hasOnlyBasemapRasters) return undefined;

    for (let i = layers.length - 1; i >= 0; i -= 1) {
      const id = layers[i]?.id;
      if (!id) continue;
      // Never use our own overlay ids as insert anchors.
      if (SI_MAPBOX_CUSTOM_LAYER_SUFFIXES.some(sfx => id.endsWith(sfx))) continue;
      if (id.includes('-vt-') || id.includes('-arcgis-')) continue;
      if (id.includes('label') || id.includes('symbol') || id.startsWith('place-')) return id;
    }
  } catch {
    /* ignore */
  }
  return undefined;
}

function siApplyMapboxPaintProps(
  map: SiMapboxCanvasLike,
  layerId: string,
  paint: Record<string, unknown>,
) {
  if (!map.getLayer(layerId) || typeof map.setPaintProperty !== 'function') return;
  const safePaint = sanitizeMapboxPaint(paint);
  for (const [name, value] of Object.entries(safePaint)) {
    try {
      map.setPaintProperty(layerId, name, value);
    } catch {
      /* ignore */
    }
  }
}

const siCustomLayerGeoJsonPaintSigBySourceId = new Map<string, string>();

function siCustomLayerGeoJsonPaintSig(geojson: unknown): string {
  const features = Array.isArray((geojson as { features?: unknown[] })?.features)
    ? (geojson as { features: unknown[] }).features
    : [];
  if (!features.length) return 'empty';
  return `n:${features.length}`;
}

function siPaintCustomLayersOnMapboxCanvas(
  map: SiMapboxCanvasLike,
  layers: CustomLayer[],
  trackedSourceIds: Set<string>,
  options?: {
    suppressPrimaryAoiFill?: boolean
    /** Extra layer ids whose polygon fill must be invisible under live Sentinel WMS. */
    suppressFillLayerIds?: ReadonlySet<string> | string[]
    onArcgisIconsLoaded?: () => void
  },
) {
  const nextSourceIds = new Set<string>();
  const beforeId = siMapboxInsertBeforeId(map);
  const suppressFillIds = new Set<string>(
    options?.suppressFillLayerIds instanceof Set
      ? [...options.suppressFillLayerIds]
      : options?.suppressFillLayerIds ?? [],
  );
  if (options?.suppressPrimaryAoiFill) {
    suppressFillIds.add(AGRO_STRUCTURES_PRIMARY_LAYER_ID);
  }

  for (const layer of layers) {
    // Layers with no geometry yet (e.g. an empty shell awaiting features) are skipped,
    // except ArcGIS raster/vector-tile layers that mount tile sources directly.
    const hasTileSource =
      (layer.arcgisRasterTiles?.tiles?.length ?? 0) > 0 || (layer.arcgisVectorTiles?.tiles?.length ?? 0) > 0;
    if (!layer.geojson && !hasTileSource) continue;
    const sourceId = siSafeMapboxLayerId(layer.id);
    nextSourceIds.add(sourceId);
    const layerVisible = layer.visible !== false;
    const op = layer.mapOpacity ?? 1;

    try {
      if (layer.arcgisRasterTiles?.tiles?.length) {
        const rasterSrcId = sourceId;
        if (!map.getSource(rasterSrcId)) {
          // Cap at the service's native zoom so Mapbox over-zooms the last real
          // tiles rather than fetching unavailable levels that cached services
          // return as gray "Map data not yet available" placeholder tiles.
          const maxNativeZoom = rasterTilesSourceMaxNativeZoom(layer.arcgisRasterTiles);
          map.addSource(rasterSrcId, {
            type: 'raster',
            tiles: layer.arcgisRasterTiles.tiles,
            tileSize: layer.arcgisRasterTiles.tileSize ?? 256,
            ...(typeof maxNativeZoom === 'number' ? { maxzoom: maxNativeZoom } : {}),
          });
          arcgisDynamicDebug('source_created', { layerId: layer.id, kind: 'arcgis-raster-tiles' });
        }
        const rasterId = `${sourceId}-arcgis-raster`;
        const rasterOpacity = 0.92 * op;
        if (!map.getLayer(rasterId)) {
          map.addLayer(
            {
              id: rasterId,
              type: 'raster',
              source: rasterSrcId,
              layout: { visibility: layerVisible ? 'visible' : 'none' },
              paint: { 'raster-opacity': rasterOpacity, 'raster-fade-duration': 0, 'raster-resampling': 'linear' },
            },
            beforeId,
          );
          arcgisDynamicDebug('layer_added', { layerId: layer.id, mapboxLayerId: rasterId });
        } else {
          siApplyMapboxPaintProps(map, rasterId, { 'raster-opacity': rasterOpacity });
          try {
            map.setLayoutProperty?.(rasterId, 'visibility', layerVisible ? 'visible' : 'none');
          } catch {
            /* ignore */
          }
        }
        continue;
      }

      if (layer.arcgisVectorTiles?.tiles?.length) {
        if (!map.getSource(sourceId)) {
          map.addSource(sourceId, {
            type: 'vector',
            tiles: layer.arcgisVectorTiles.tiles,
            minzoom: layer.arcgisVectorTiles.minzoom ?? 0,
            maxzoom: layer.arcgisVectorTiles.maxzoom ?? 22,
          });
          arcgisDynamicDebug('source_created', { layerId: layer.id, kind: 'arcgis-vector-tiles' });
        }
        const sourceLayers = layer.arcgisVectorTiles.sourceLayers?.length
          ? layer.arcgisVectorTiles.sourceLayers
          : ['layer'];
        const initialVisibility = { visibility: layerVisible ? 'visible' : 'none' } as const;
        sourceLayers.forEach((srcLayer, idx) => {
          const safe = srcLayer.replace(/[^a-zA-Z0-9_-]/g, '_') || `layer-${idx}`;
          const fillId = `${sourceId}-vt-fill-${safe}`;
          const lineId = `${sourceId}-vt-line-${safe}`;
          if (!map.getLayer(fillId)) {
            map.addLayer(
              {
                id: fillId,
                type: 'fill',
                source: sourceId,
                'source-layer': srcLayer,
                layout: initialVisibility,
                paint: {
                  'fill-color': layer.fillColor || layer.color || '#38bdf8',
                  'fill-opacity': (layer.polygonFillAlpha ?? 0.35) * op,
                },
              },
              beforeId,
            );
            arcgisDynamicDebug('layer_added', { layerId: layer.id, mapboxLayerId: fillId });
          }
          if (!map.getLayer(lineId)) {
            map.addLayer(
              {
                id: lineId,
                type: 'line',
                source: sourceId,
                'source-layer': srcLayer,
                layout: initialVisibility,
                paint: {
                  'line-color': layer.color || '#38bdf8',
                  'line-width': layer.weight ?? 1.5,
                  'line-opacity': op,
                },
              },
              beforeId,
            );
            arcgisDynamicDebug('layer_added', { layerId: layer.id, mapboxLayerId: lineId });
          } else {
            try {
              map.setLayoutProperty?.(fillId, 'visibility', layerVisible ? 'visible' : 'none');
              map.setLayoutProperty?.(lineId, 'visibility', layerVisible ? 'visible' : 'none');
            } catch {
              /* ignore */
            }
          }
        });
        continue;
      }

      if (layer.renderMode === 'raster' && layer.raster?.url && layer.raster.coordinates) {
        const rasterOpacity = isWellSuitabilityMcdaLayerId(layer.id) ? op : op;
        syncMapboxGeoreferencedImageLayer(map, sourceId, layer.raster.url, layer.raster.coordinates, {
          visible: layerVisible,
          opacity: rasterOpacity,
          beforeId,
        });
        continue;
      }

      const src = map.getSource(sourceId) as { setData?: (d: unknown) => void } | undefined;
      const paintSig = siCustomLayerGeoJsonPaintSig(layer.geojson);
      const prevPaintSig = siCustomLayerGeoJsonPaintSigBySourceId.get(sourceId);
      if (src?.setData) {
        if (paintSig !== prevPaintSig) {
          src.setData(layer.geojson);
          siCustomLayerGeoJsonPaintSigBySourceId.set(sourceId, paintSig);
        }
      } else {
        siCustomLayerGeoJsonPaintSigBySourceId.delete(sourceId);
        siRemoveMapboxCustomLayerStack(map, sourceId);
        map.addSource(sourceId, {
          type: 'geojson',
          data: layer.geojson,
          tolerance: 0.8,
          buffer: 64,
          maxzoom: 14,
        });
      }

      const st = siLayerMapboxStylePack(layer);
      let fillPaint = sanitizeMapboxPaint(siScalePaintOpacityByFactor(st.fillPaint as Record<string, unknown>, op));
      if (suppressFillIds.has(String(layer.id))) {
        fillPaint = { ...fillPaint, 'fill-opacity': 0 };
      }
      const linePaint = sanitizeMapboxPaint(
        siMapboxZoomScaledLinePaint(
          siScalePaintOpacityByFactor(st.linePaint as Record<string, unknown>, op),
          op,
        ),
      );
      const circlePaintRaw = sanitizeMapboxPaint(
        siScalePaintOpacityByFactor(st.circlePaint as Record<string, unknown>, op),
      );
      let circlePaint =
        op < 0.999 && circlePaintRaw['circle-opacity'] === undefined
          ? { ...circlePaintRaw, 'circle-opacity': op }
          : circlePaintRaw;

      // Marker mode: points render as a registered icon (e.g. water-drop). The
      // circle stays mounted but fully transparent so hit-testing / identify keep
      // working; the visible glyph is the icon symbol drawn on top.
      const markerImageId = layer.markerImageId;
      const useMarker = !!markerImageId && siEnsureWaterDropImage(map, markerImageId);
      if (useMarker) {
        circlePaint = {
          ...circlePaint,
          'circle-radius': typeof layer.pointRadius === 'number' ? Math.max(6, layer.pointRadius) : 8,
          'circle-opacity': 0,
          'circle-stroke-width': 0,
        };
      }

      const arcgisIconId = `${sourceId}-arcgis-icon`;
      const pointGeomKind = resolveLayerGeometryKind(layer.geojson, layer.arcgisLayerDefinition);
      const overlayGeomKind =
        (layer as { importMetadata?: { geometryType?: string } }).importMetadata?.geometryType ||
        detectImportedGeometryKind(layer.geojson, layer.arcgisLayerDefinition, layer.renderMode);
      const pointIconSpec =
        !useMarker &&
        siLayerUsesArcgisOnlineSymbology(layer) &&
        pointGeomKind === 'point' &&
        resolveLayerArcgisDrawingInfo(layer)
          ? buildArcgisPointIconLayerSpec(resolveLayerArcgisDrawingInfo(layer), sourceId)
          : null;
      let useArcgisPointIcons = false;
      if (pointIconSpec) {
        useArcgisPointIcons = siEnsureArcgisPointIconImages(map, pointIconSpec, () => {
          options?.onArcgisIconsLoaded?.();
        });
        if (useArcgisPointIcons) {
          circlePaint = {
            ...circlePaint,
            'circle-radius':
              typeof circlePaint['circle-radius'] === 'number'
                ? Math.max(4, circlePaint['circle-radius'] as number)
                : 6,
            'circle-opacity': 0,
            'circle-stroke-width': 0,
          };
        }
      }

      const fillId = `${sourceId}-fill`;
      const lineId = `${sourceId}-line`;
      const circleId = `${sourceId}-circle`;
      const markerId = `${sourceId}-marker`;
      const labelId = `${sourceId}-label`;

      // Definition query — combine the user's compiled filter (e.g. `crop = wheat`)
      // with each geometry-type base filter so only matching features are drawn.
      const defFilter =
        Array.isArray(layer.definitionFilter) && layer.definitionFilter.length ? layer.definitionFilter : null;
      const withDef = (base: unknown): unknown =>
        defFilter ? (Array.isArray(base) ? ['all', base, defFilter] : defFilter) : base;
      const fillFilter = withDef(st.fillFilter);
      const lineFilter = withDef(st.lineFilter);
      const pointFilter = withDef(st.pointFilter);
      // Polygon/line GIS imports often include stray Point features — never paint
      // those as blue/black marker dots unless the layer is primarily points.
      const paintCircles =
        shouldPaintImportedLayerCircles(overlayGeomKind as any) || useMarker || useArcgisPointIcons;

      const initialVisibility = { visibility: layerVisible ? 'visible' : 'none' } as const;
      if (!map.getLayer(fillId)) {
        map.addLayer({ id: fillId, type: 'fill', source: sourceId, filter: fillFilter, layout: initialVisibility, paint: fillPaint }, beforeId);
      } else {
        siApplyMapboxPaintProps(map, fillId, fillPaint);
        try { map.setFilter?.(fillId, fillFilter); } catch { /* ignore */ }
      }
      if (!map.getLayer(lineId)) {
        map.addLayer({ id: lineId, type: 'line', source: sourceId, filter: lineFilter, layout: initialVisibility, paint: linePaint }, beforeId);
      } else {
        siApplyMapboxPaintProps(map, lineId, linePaint);
        try { map.setFilter?.(lineId, lineFilter); } catch { /* ignore */ }
      }
      if (paintCircles) {
        if (!map.getLayer(circleId)) {
          map.addLayer({ id: circleId, type: 'circle', source: sourceId, filter: pointFilter, layout: initialVisibility, paint: circlePaint }, beforeId);
        } else {
          siApplyMapboxPaintProps(map, circleId, circlePaint);
          try { map.setFilter?.(circleId, pointFilter); } catch { /* ignore */ }
          try { map.setLayoutProperty?.(circleId, 'visibility', layerVisible ? 'visible' : 'none'); } catch { /* ignore */ }
        }
      } else if (map.getLayer(circleId)) {
        try { map.setLayoutProperty?.(circleId, 'visibility', 'none'); } catch { /* ignore */ }
      }

      // Icon marker (water-drop) drawn above the transparent circle.
      if (useMarker) {
        const markerSize = typeof layer.pointRadius === 'number' ? Math.max(0.6, layer.pointRadius / 9) : 0.85;
        const markerLayout = {
          visibility: layerVisible ? 'visible' : 'none',
          'icon-image': markerImageId,
          'icon-size': markerSize,
          'icon-anchor': 'bottom',
          'icon-allow-overlap': true,
          'icon-ignore-placement': true,
        };
        const markerPaint = { 'icon-opacity': op };
        if (!map.getLayer(markerId)) {
          map.addLayer({ id: markerId, type: 'symbol', source: sourceId, filter: pointFilter, layout: markerLayout, paint: markerPaint }, beforeId);
        } else {
          try {
            map.setLayoutProperty?.(markerId, 'icon-image', markerImageId);
            map.setLayoutProperty?.(markerId, 'icon-size', markerSize);
            map.setFilter?.(markerId, pointFilter);
          } catch { /* ignore */ }
          siApplyMapboxPaintProps(map, markerId, markerPaint);
        }
      } else if (map.getLayer(markerId)) {
        try { map.removeLayer(markerId); } catch { /* ignore */ }
      }

      if (useArcgisPointIcons && pointIconSpec) {
        const iconLayout = {
          visibility: layerVisible ? 'visible' : 'none',
          'icon-image': buildArcgisPointIconImageMatch(pointIconSpec),
          'icon-size': pointIconSpec.iconSize,
          'icon-allow-overlap': true,
          'icon-ignore-placement': true,
        };
        const iconPaint = { 'icon-opacity': op };
        if (!map.getLayer(arcgisIconId)) {
          map.addLayer(
            { id: arcgisIconId, type: 'symbol', source: sourceId, filter: pointFilter, layout: iconLayout, paint: iconPaint },
            beforeId,
          );
        } else {
          try {
            map.setLayoutProperty?.(arcgisIconId, 'icon-image', iconLayout['icon-image']);
            map.setLayoutProperty?.(arcgisIconId, 'icon-size', iconLayout['icon-size']);
            map.setFilter?.(arcgisIconId, pointFilter);
          } catch {
            /* ignore */
          }
          siApplyMapboxPaintProps(map, arcgisIconId, iconPaint);
        }
      } else if (map.getLayer(arcgisIconId)) {
        try {
          map.removeLayer(arcgisIconId);
        } catch {
          /* ignore */
        }
      }

      // Labeling — one text label per feature from the chosen attribute field + style.
      const labelField =
        typeof layer.labelFieldName === 'string' && layer.labelFieldName.trim() ? layer.labelFieldName.trim() : '';
      if (labelField) {
        const labelStyle = normalizeSiLayerLabelStyle({
          ...DEFAULT_SI_LAYER_LABEL_STYLE,
          ...(layer.labelStyle ?? {}),
          fieldName: labelField,
        });
        const textField = ['to-string', ['get', labelField]];
        const textFont = resolveSiLabelMapboxFontStack(labelStyle);
        const labelLayout = {
          visibility: layerVisible ? 'visible' : 'none',
          'text-field': textField,
          'text-size': labelStyle.fontSize,
          'text-font': textFont,
          'text-anchor': 'center',
          'text-justify': 'center',
          'text-allow-overlap': true,
          'text-ignore-placement': true,
          'text-optional': false,
          'text-padding': 1,
          'text-max-width': 10,
          'symbol-placement': 'point',
        };
        const labelPaint = {
          'text-color': labelStyle.textColor,
          'text-halo-color': labelStyle.haloColor,
          'text-halo-width': labelStyle.haloWidth,
          'text-opacity': op,
        };
        const hasTextFilter = [
          'all',
          ['has', labelField],
          ['!=', ['to-string', ['get', labelField]], ''],
          ['!=', ['to-string', ['get', labelField]], 'null'],
        ];
        const labelFilter = defFilter ? ['all', defFilter, hasTextFilter] : hasTextFilter;
        if (!map.getLayer(labelId)) {
          map.addLayer(
            {
              id: labelId,
              type: 'symbol',
              source: sourceId,
              minzoom: labelStyle.minZoom,
              maxzoom: labelStyle.maxZoom,
              filter: labelFilter,
              layout: labelLayout,
              paint: labelPaint,
            },
            beforeId,
          );
        } else {
          try {
            map.setLayoutProperty?.(labelId, 'text-field', textField);
            map.setLayoutProperty?.(labelId, 'text-size', labelStyle.fontSize);
            map.setLayoutProperty?.(labelId, 'text-font', textFont);
            map.setLayoutProperty?.(labelId, 'text-allow-overlap', true);
            map.setLayoutProperty?.(labelId, 'text-ignore-placement', true);
            map.setFilter?.(labelId, labelFilter);
            map.setLayerZoomRange?.(labelId, labelStyle.minZoom, labelStyle.maxZoom);
          } catch {
            /* ignore */
          }
          siApplyMapboxPaintProps(map, labelId, labelPaint);
        }
      } else if (map.getLayer(labelId)) {
        try {
          map.removeLayer(labelId);
        } catch {
          /* ignore */
        }
      }

      // Sync the show/hide toggle to the map: flip every sub-layer's `visibility`
      // in lock-step so fill + line + circle + label respond together and the draw
      // order is preserved when the layer is switched back on.
      siSetMapboxCustomLayerStackVisibility(map, sourceId, layerVisible);
    } catch (err) {
      console.warn('Satellite Intelligence: could not paint custom layer on map canvas', sourceId, err);
    }
  }

  // Only layers that were truly removed from the panel (not merely hidden) are torn
  // down here â€” hidden layers stay mounted with visibility:none for instant toggling.
  for (const staleId of trackedSourceIds) {
    if (!nextSourceIds.has(staleId)) siRemoveMapboxCustomLayerStack(map, staleId);
  }
  trackedSourceIds.clear();
  nextSourceIds.forEach(id => trackedSourceIds.add(id));

  // Guarantee overlays sit above basemap rasters (style diffs can bury them).
  siRaiseCustomLayersAboveBasemap(map, trackedSourceIds);

  try {
    map.triggerRepaint?.();
  } catch {
    /* ignore */
  }
}

/** Mapbox layer id `${sourceId}-fill|line|circle|cluster|cluster-count` â†’ custom layer source id. */
function siVectorLayerIdToCustomSourceId(mapboxLayerId: string): string | null {
  const m = mapboxLayerId.match(/^(.+)-(fill|line|circle|marker|cluster|cluster-count)$/);
  return m ? m[1] : null;
}

function siIdentifyLayerIsSkippable(layerId: string): boolean {
  if (!layerId) return true;
  if (layerId.startsWith('si-crop-alert-')) return true;
  if (layerId.startsWith('si-geo-ai-pin')) return true;
  if (layerId.startsWith('si-geo-ai-sel-')) return true;
  if (layerId.startsWith('si-draw-draft')) return true;
  if (layerId.startsWith('si-edit-handles')) return true;
  if (layerId === 'sentinel-layer' || isSiSentinelAoiWmsMapLayerId(layerId) || layerId === 'si-stac-thumb-layer') return true;
  if (layerId === 'background') return true;
  return false;
}

function siGeoJsonPointishFeatureCount(gj: unknown): number {
  if (!gj || typeof gj !== 'object') return 0;
  const feats = (gj as { features?: unknown[] }).features;
  if (!Array.isArray(feats)) return 0;
  let n = 0;
  for (const ft of feats) {
    const g = (ft as { geometry?: { type?: string; coordinates?: unknown } })?.geometry;
    const t = g?.type;
    if (t === 'Point') n += 1;
    else if (t === 'MultiPoint' && Array.isArray(g?.coordinates)) n += g.coordinates.length;
  }
  return n;
}

function siCustomLayerShouldClusterPoints(layer: { renderMode?: string; geojson?: unknown }): boolean {
  if (layer.renderMode === 'raster' || !layer.geojson) return false;
  return siGeoJsonPointishFeatureCount(layer.geojson) >= GEO_AI_CLUSTER_POINT_THRESHOLD;
}

function siIdentifyTitleForLayerId(layerId: string, customLayers: CustomLayer[]): string {
  const sid = siVectorLayerIdToCustomSourceId(layerId);
  if (sid) {
    const c = customLayers.find(l => siSafeMapboxLayerId(l.id) === sid);
    if (c?.name) return c.name;
  }
  if (layerId === AGRI_FIELD_BOUNDARY_FILL_ID || layerId === AGRI_FIELD_BOUNDARY_OUTLINE_ID) {
    return 'Field boundaries';
  }
  if (layerId.startsWith('agri-pivots')) return 'Pivot markers';
  if (layerId.startsWith('si-stac-footprints')) return 'STAC footprint';
  if (layerId.startsWith('drawn-index-geometry')) return 'Drawn AOI';
  return layerId.replace(/-(fill|line|circle)$/, '') || 'Feature';
}

function siResolveIdentifyCustomLayer(
  layerId: string,
  customLayers: CustomLayerIdentifyMeta[],
  agriFieldBoundaryGeojson: GeoJSON.FeatureCollection | null | undefined,
): CustomLayerIdentifyMeta | null {
  if (layerId === AGRI_FIELD_BOUNDARY_FILL_ID || layerId === AGRI_FIELD_BOUNDARY_OUTLINE_ID) {
    const count = Array.isArray(agriFieldBoundaryGeojson?.features)
      ? agriFieldBoundaryGeojson.features.length
      : 0;
    if (!count) return null;
    return {
      id: AGRI_FIELD_BOUNDARY_PREVIEW_LAYER_ID,
      name: `Field boundaries (${count})`,
      geojson: agriFieldBoundaryGeojson ?? undefined,
    };
  }
  return resolveCustomLayerFromMapboxHit(layerId, customLayers);
}

function siArcgisDefForIdentifyLayerId(layerId: string, customLayers: CustomLayer[]): ArcgisLayerDefLite | null {
  const sid = siVectorLayerIdToCustomSourceId(layerId);
  if (!sid) return null;
  const c = customLayers.find(l => siSafeMapboxLayerId(l.id) === sid);
  return c?.arcgisLayerDefinition && typeof c.arcgisLayerDefinition === 'object' ? c.arcgisLayerDefinition : null;
}

function siSanitizeIdentifyProperties(raw: Record<string, unknown> | null | undefined): Record<string, unknown> {
  if (!raw || typeof raw !== 'object') return {};
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(raw)) {
    if (k.startsWith('mapbox_')) continue;
    if (k === 'layer' || k === 'id' || k === 'source_layer') continue;
    out[k] = v;
  }
  return out;
}

/** Line / point fallback when honoring ArcGIS drawingInfo â€” avoids Mapbox brand greens on service symbology. */
const SI_ARCGIS_MAPBOX_NEUTRAL_LINE = 'rgba(148, 163, 184, 0.55)';
const SI_ARCGIS_MAPBOX_NEUTRAL_STROKE = 'rgba(15, 23, 42, 0.72)';

function siArcgisDrawingInfoFetchUrl(
  layer: Pick<CustomLayer, 'id' | 'sourceUrl' | 'name' | 'source'>,
): string {
  const raw = String(layer.sourceUrl || '').trim();
  if (!raw) return '';

  const portalId = parseGisContentPortalLayerUrl(raw);
  if (portalId) {
    const row = getGisContentRowById(portalId);
    const external = row ? resolveHostedFeatureLayerExternalUrl(row) : null;
    if (external) {
      return isAgroStructuresLayer(layer) ? resolveAgroStructuresLayerUrl(external) : external;
    }
    return '';
  }

  if (isAgroStructuresLayer(layer)) {
    return resolveAgroStructuresLayerUrl(raw || AGRO_STRUCTURES_FS21_URL);
  }

  if (/https?:\/\//i.test(raw) && /\/(FeatureServer|MapServer)\/\d+\/?$/i.test(raw)) {
    return raw;
  }

  return layer.source === 'arcgis' ? raw : '';
}

function siLayerHasArcgisRestSource(
  layer: Pick<CustomLayer, 'id' | 'sourceUrl' | 'name' | 'source'>,
): boolean {
  return Boolean(siArcgisDrawingInfoFetchUrl(layer));
}

function siLayerSupportsArcgisOnlineSymbology(layer: CustomLayer): boolean {
  if (layer.renderMode === 'raster') return false;
  if (layer.arcgisServiceType === 'map' || layer.arcgisServiceType === 'image') return false;
  return siLayerHasArcgisRestSource(layer);
}

function siApplyArcgisOnlineSymbologyOnImport(layer: CustomLayer): CustomLayer {
  if (!siLayerSupportsArcgisOnlineSymbology(layer)) return layer;
  const serviceDi =
    layer.arcgisDrawingInfoService ??
    (layer.arcgisDrawingInfo ? (layer.arcgisDrawingInfo as Record<string, unknown>) : undefined);
  return {
    ...layer,
    useArcGisSymbology: true,
    symbology: {
      ...(layer.symbology ?? {}),
      useArcGisOnline: true,
    },
    arcgisDrawingInfoService: serviceDi,
    arcgisDrawingInfo: undefined,
  };
}

/** Whether the user wants ArcGIS Online renderer symbology (vs Symbology Studio overrides). */
function siLayerWantsArcgisOnlineSymbology(layer: CustomLayer): boolean {
  if (layer.symbology?.useArcGisOnline === true) return true;
  if (layer.symbology?.useArcGisOnline === false) return false;
  if (layer.useArcGisSymbology === true) return true;
  if (layer.useArcGisSymbology === false) return false;
  return layer.source === 'arcgis' || siLayerHasArcgisRestSource(layer);
}

/** Whether the map can paint vectors using ArcGIS `drawingInfo` right now. */
function siLayerUsesArcgisOnlineSymbology(layer: CustomLayer): boolean {
  if (!siLayerWantsArcgisOnlineSymbology(layer)) return false;
  return Boolean(resolveLayerArcgisDrawingInfo(layer));
}

function siArcgisDrawingTransparencyFactor(drawingInfo: unknown): number {
  const t = (drawingInfo as { transparency?: unknown } | null)?.transparency;
  if (typeof t !== 'number' || !Number.isFinite(t)) return 1;
  return Math.max(0, Math.min(1, 1 - t / 100));
}

function siRasterLayerPaintSig(layer: CustomLayer): string {
  if (layer.renderMode !== 'raster' || !layer.raster) return '';
  const coords = layer.raster.coordinates;
  const coordSig = Array.isArray(coords)
    ? coords.map(p => `${Number(p[0]).toFixed(6)},${Number(p[1]).toFixed(6)}`).join(';')
    : '';
  const urlTail = layer.raster.url ? layer.raster.url.slice(-32) : '';
  return `raster:${urlTail}:${coordSig}`;
}

function pickSiCustomLayerStyleSnapshot(l: CustomLayer): Partial<CustomLayer> {
  return {
    symbology: l.symbology ? { ...l.symbology } : undefined,
    color: l.color,
    fillColor: l.fillColor,
    weight: l.weight,
    strokeStyle: l.strokeStyle,
    polygonFillAlpha: l.polygonFillAlpha,
    pointRadius: l.pointRadius,
    fillStyle: l.fillStyle,
    blendMode: l.blendMode,
    mapOpacity: l.mapOpacity,
    useArcGisSymbology: l.useArcGisSymbology,
    arcgisDrawingInfo: l.arcgisDrawingInfo,
    arcgisDrawingInfoService: l.arcgisDrawingInfoService,
  };
}

function siLayerMapboxStylePack(layer: CustomLayer): {
  fillFilter: any;
  lineFilter: any;
  pointFilter: any;
  fillPaint: Record<string, unknown>;
  linePaint: Record<string, unknown>;
  circlePaint: Record<string, unknown>;
} {
  const wantsAg = siLayerWantsArcgisOnlineSymbology(layer);
  const resolvedDi = resolveLayerArcgisDrawingInfo(layer);
  const useAg = wantsAg && Boolean(resolvedDi);
  const geomKind = resolveLayerGeometryKind(layer.geojson, layer.arcgisLayerDefinition);
  if (wantsAg && !resolvedDi) {
    // Until ArcGIS drawingInfo arrives, keep features visible with portal-style defaults
    // (fill-opacity 0 made Agro/KML-style ArcGIS layers look "missing" on the canvas).
    const portal = siDefaultPortalVectorLayerFields();
    return {
      fillFilter: SI_MAPBOX_POLY_FILTER,
      lineFilter: SI_MAPBOX_LINE_POLY_FILTER,
      pointFilter: SI_MAPBOX_POINT_FILTER,
      fillPaint: {
        'fill-color': layer.fillColor || portal.fillColor || '#22c55e',
        'fill-opacity': typeof layer.polygonFillAlpha === 'number' ? layer.polygonFillAlpha : 0.35,
      },
      linePaint: {
        'line-color': layer.color || portal.color || '#16a34a',
        'line-width': typeof layer.weight === 'number' ? layer.weight : 2,
        'line-opacity': 0.95,
      },
      circlePaint: {
        'circle-radius': typeof layer.pointRadius === 'number' ? layer.pointRadius : 6,
        'circle-color': layer.fillColor || layer.color || '#22c55e',
        'circle-stroke-width': 1.5,
        'circle-stroke-color': '#0f172a',
        'circle-opacity': 0.95,
      },
    };
  }
  if (useAg) {
    const di = resolvedDi as any;
    const transparencyFactor = siArcgisDrawingTransparencyFactor(di);
    let fill = arcgisDrawingInfoToFillPaint(di);
    let line = arcgisDrawingInfoToLinePaint(di, SI_ARCGIS_MAPBOX_NEUTRAL_LINE);
    let circle = geomKind === 'point' ? arcgisDrawingInfoToCirclePaint(di) : null;
    if (!circle && geomKind === 'point') {
      console.warn('[si-point-symbol] Failed to map ArcGIS point symbology to Mapbox circle paint', {
        layerId: layer.id,
        rendererType: di?.renderer?.type,
      });
    }
    if (fill && transparencyFactor < 0.999) {
      fill = siScalePaintOpacityByFactor(fill as Record<string, unknown>, transparencyFactor) as typeof fill;
    }
    if (line && transparencyFactor < 0.999) {
      line = siScalePaintOpacityByFactor(line as Record<string, unknown>, transparencyFactor) as typeof line;
    }
    if (circle && transparencyFactor < 0.999) {
      circle = siScalePaintOpacityByFactor(circle, transparencyFactor);
    }
    if (geomKind === 'point' && circle) {
      return {
        fillFilter: SI_MAPBOX_POLY_FILTER,
        lineFilter: SI_MAPBOX_LINE_ONLY_FILTER,
        pointFilter: SI_MAPBOX_POINT_FILTER,
        fillPaint: { 'fill-color': 'rgba(0,0,0,0)', 'fill-opacity': 0 },
        linePaint: (line ?? {
          'line-color': SI_ARCGIS_MAPBOX_NEUTRAL_LINE,
          'line-width': 1,
          'line-opacity': 0,
        }) as Record<string, unknown>,
        circlePaint: circle,
      };
    }
    if (fill) {
      return {
        fillFilter: SI_MAPBOX_POLY_FILTER,
        // Always draw polygon rings on the line layer — outline-only ArcGIS subtypes
        // (PIVOT, Farm Plots, Dates Farm) rely on line-color; fill-outline-color alone
        // hides features when match keys miss.
        lineFilter: SI_MAPBOX_LINE_POLY_FILTER,
        pointFilter: SI_MAPBOX_POINT_FILTER,
        fillPaint: fill as Record<string, unknown>,
        linePaint: (line ?? {
          'line-color': SI_ARCGIS_MAPBOX_NEUTRAL_LINE,
          'line-width': 1.5,
          'line-opacity': 0.95,
        }) as Record<string, unknown>,
        circlePaint: {
          'circle-radius': 4,
          'circle-color': SI_ARCGIS_MAPBOX_NEUTRAL_LINE,
          'circle-stroke-width': 1,
          'circle-stroke-color': SI_ARCGIS_MAPBOX_NEUTRAL_STROKE,
        },
      };
    }
    return {
      fillFilter: SI_MAPBOX_POLY_FILTER,
      lineFilter: SI_MAPBOX_LINE_POLY_FILTER,
      pointFilter: SI_MAPBOX_POINT_FILTER,
      fillPaint: { 'fill-color': 'rgba(0,0,0,0)', 'fill-opacity': 0 },
      linePaint: (line ?? {
        'line-color': SI_ARCGIS_MAPBOX_NEUTRAL_LINE,
        'line-width': 1.25,
        'line-opacity': 0.85,
      }) as Record<string, unknown>,
      circlePaint: {
        'circle-radius': 4,
        'circle-color': SI_ARCGIS_MAPBOX_NEUTRAL_LINE,
        'circle-stroke-width': 1,
        'circle-stroke-color': SI_ARCGIS_MAPBOX_NEUTRAL_STROKE,
      },
    };
  }
  return buildSiCustomVectorStylePack({
    geojson: layer.geojson,
    source: layer.source,
    symbology: layer.symbology,
    color: layer.color,
    fillColor: layer.fillColor,
    weight: layer.weight,
    strokeStyle: layer.strokeStyle as any,
    polygonFillAlpha: layer.polygonFillAlpha,
    pointRadius: layer.pointRadius,
    fillStyle: layer.fillStyle as any,
    canUseArcGisOnline:
      layer.source === 'arcgis' ||
      siLayerHasArcgisRestSource(layer) ||
      Boolean(layer.arcgisDrawingInfo) ||
      Boolean((layer.arcgisLayerDefinition as any)?.drawingInfo),
  });
}

function siNormalizeLayerGeojsonForSymbology(layer: CustomLayer): CustomLayer['geojson'] {
  if (!siLayerWantsArcgisOnlineSymbology(layer) || !isAgroStructuresLayer(layer)) return layer.geojson;
  const features = layer.geojson?.features;
  if (!Array.isArray(features) || !features.length) return layer.geojson;
  return {
    ...layer.geojson,
    features: features.map(f => normalizeAgroStructuresFeatureForSymbology(f) as GeoJSON.Feature),
  };
}

/** Multiply numeric *-opacity paint props for per-layer transparency (Mapbox GL). */
function siScalePaintOpacityByFactor(paint: Record<string, unknown>, factor: number): Record<string, unknown> {
  if (!paint || factor >= 0.999) return paint;
  const out: Record<string, unknown> = { ...paint };
  for (const [k, v] of Object.entries(out)) {
    if (!k.includes('opacity')) continue;
    if (typeof v === 'number' && Number.isFinite(v)) {
      out[k] = Math.min(1, Math.max(0, v * factor));
    }
  }
  return out;
}

function persistCustomLayersToStorage(layers: CustomLayer[], storageKey = SATELLITE_CUSTOM_LAYERS_STORAGE_KEY) {
  if (typeof window === 'undefined') return;
  try {
    const storable = slimArcGisLayersForStorage(layers.filter(l => !l.ephemeral));
    window.localStorage.setItem(storageKey, JSON.stringify(storable));
  } catch (e) {
    console.warn('Satellite Intelligence: could not persist custom layers', e);
  }
}

