  const [cropAiGeoTiffBusy, setCropAiGeoTiffBusy] = useState(false);
  const [cropAiGeoTiffLabel, setCropAiGeoTiffLabel] = useState<string | undefined>(undefined);
  const handleCropAiExportReport = useCallback(() => {
    const geom = drawnGeometry?.geometry;
    const result = cropAiJob?.status === 'done' ? cropAiJob.result : null;
    if (!geom || (geom.type !== 'Polygon' && geom.type !== 'MultiPolygon') || !result) return;
    setCropAiExportBusy(true);
    setCropAiExportLabel('Preparing report…');
    void (async () => {
      try {
        await generateCropClassificationReportDocx({
          geometry: geom,
          aoiName:
            (drawnGeometry?.properties?.name as string | undefined) ??
            (drawnGeometry?.properties?.fieldName as string | undefined) ??
            'Crop Study Area',
          season: cropAiSeason,
          result,
          projectName: 'AgroCloud Crop Classification Intelligence',
          generatedBy: 'AgroCloud',
          onProgress: (done, total, label) => {
            setCropAiExportLabel(`Maps ${done}/${total}: ${label}`);
          },
        });
      } catch (err) {
        console.error('Crop classification report export failed', err);
      } finally {
        setCropAiExportBusy(false);
        setCropAiExportLabel(undefined);
      }
    })();
  }, [drawnGeometry, cropAiJob, cropAiSeason]);

  const handleCropAiExportGeoTiff = useCallback(() => {
    const result = cropAiJob?.status === 'done' ? cropAiJob.result : null;
    if (!result?.prediction?.url || !result.prediction.bounds) return;
    const geom = drawnGeometry?.geometry;
    setCropAiGeoTiffBusy(true);
    setCropAiGeoTiffLabel('Preparing GeoTIFF…');
    void (async () => {
      try {
        await exportCropClassificationGeoTiff({
          result,
          aoiName:
            (drawnGeometry?.properties?.name as string | undefined) ??
            (drawnGeometry?.properties?.fieldName as string | undefined) ??
            'Crop Study Area',
          geometry:
            geom && (geom.type === 'Polygon' || geom.type === 'MultiPolygon') ? geom : null,
          onProgress: label => setCropAiGeoTiffLabel(label),
        });
      } catch (err) {
        console.error('Crop classification GeoTIFF export failed', err);
      } finally {
        setCropAiGeoTiffBusy(false);
        setCropAiGeoTiffLabel(undefined);
      }
    })();
  }, [drawnGeometry, cropAiJob]);

  const clipRasterToAoi = useCallback(
    async (
      imageUrl: string,
      bounds: [number, number, number, number],
      geometry: unknown,
    ): Promise<string> => {
      const geom = getDrawnGeometry(geometry);
      const rings: number[][][] =
        geom?.type === 'Polygon'
          ? (geom.coordinates as unknown as number[][][])
          : geom?.type === 'MultiPolygon'
            ? (geom.coordinates as unknown as number[][][][]).flat()
            : [];
      if (!rings.length) return imageUrl;
      try {
        const img = await new Promise<HTMLImageElement>((resolve, reject) => {
          const im = new Image();
          if (/^https?:\/\//i.test(imageUrl)) im.crossOrigin = 'anonymous';
          im.onload = () => resolve(im);
          im.onerror = reject;
          im.src = imageUrl;
        });
        const W = img.naturalWidth || 224;
        const H = img.naturalHeight || 224;
        const canvas = document.createElement('canvas');
        canvas.width = W;
        canvas.height = H;
        const ctx = canvas.getContext('2d');
        if (!ctx) return imageUrl;
        ctx.drawImage(img, 0, 0, W, H);
        const [w, s, e, n] = bounds;
        const toPx = (lng: number, lat: number): [number, number] => [
          ((lng - w) / (e - w)) * W,
          ((n - lat) / (n - s)) * H,
        ];
        ctx.globalCompositeOperation = 'destination-in';
        ctx.beginPath();
        for (const ring of rings) {
          ring.forEach((pt, i) => {
            const [px, py] = toPx(pt[0], pt[1]);
            if (i === 0) ctx.moveTo(px, py);
            else ctx.lineTo(px, py);
          });
          ctx.closePath();
        }
        ctx.fill('evenodd');
        ctx.globalCompositeOperation = 'source-over';
        const blob = await new Promise<Blob | null>(res => canvas.toBlob(res, 'image/png'));
        return blob ? URL.createObjectURL(blob) : imageUrl;
      } catch {
        return imageUrl;
      }
    },
    [],
  );

  const addCropAiPredictionLayer = useCallback(
    async (job: CropClassificationJob | null) => {
      const url = job?.result?.prediction?.url;
      if (!url) return;
      const aoiGeometry =
        getDrawnGeometry(cropAiAoiRef.current) ??
        getDrawnGeometry(drawnGeometryRef.current) ??
        getDrawnGeometry(drawnGeometry);
      const boundsTuple = resolveCropAiPredictionBounds(job, aoiGeometry);
      if (!boundsTuple) return;
      const [w, s, e, n] = boundsTuple;
      const coordinates = cropAiBoundsToCoordinates(boundsTuple);
      const proxiedUrl = cropPredictionImageUrl(url, job?.id);
      const finalUrl = await resolveCropAiMapImageUrl(proxiedUrl);
      if (!finalUrl || finalUrl.startsWith('data:')) {
        console.warn('[Crop AI] Map layer skipped — prediction image could not be prepared for Mapbox.');
        return;
      }
      const outline = aoiGeometry
        ? { type: 'FeatureCollection', features: [{ type: 'Feature', properties: {}, geometry: aoiGeometry }] }
        : siRasterExtentFootprint(coordinates);
      const overlay: CropAiMapOverlayState = {
        url: finalUrl,
        coordinates,
        opacity: 0.92,
        bounds: boundsTuple,
      };
      if (
        cropAiMapOverlayRef.current?.url?.startsWith('blob:') &&
        cropAiMapOverlayRef.current.url !== finalUrl
      ) {
        URL.revokeObjectURL(cropAiMapOverlayRef.current.url);
      }
      cropAiMapOverlayRef.current = overlay;
      setCropAiMapOverlay(overlay);
      setCustomLayers(prev => {
        const stale = prev.find(l => l.id === CROP_AI_PREDICTION_LAYER_ID);
        if (stale?.raster?.url?.startsWith('blob:') && stale.raster.url !== finalUrl) {
          URL.revokeObjectURL(stale.raster.url);
        }
        const without = prev.filter(l => l.id !== CROP_AI_PREDICTION_LAYER_ID);
        return [
          ...without,
          {
            id: CROP_AI_PREDICTION_LAYER_ID,
            name: 'Crop Type',
            geojson: outline,
            visible: true,
            source: 'api',
            renderMode: 'raster',
            raster: { url: finalUrl, coordinates },
            ephemeral: true,
            mapOpacity: 0.9,
          },
        ];
      });
      setCustomLayersMapEpoch(epoch => epoch + 1);
      const map = mapRef.current?.getMap ? mapRef.current.getMap() : mapRef.current;
      if (map) {
        siImperativeCustomLayerSourceIdsRef.current.add(CROP_AI_PREDICTION_SOURCE_ID);
        syncCropAiPredictionOnMapbox(map, overlay);
      }
      if (map && typeof map.fitBounds === 'function') {
        try {
          map.fitBounds(
            [
              [w, s],
              [e, n],
            ],
            { padding: 72, duration: 700, maxZoom: 16 },
          );
        } catch {
          /* ignore */
        }
      }
    },
    [drawnGeometry],
  );

  // Re-assert Crop AI raster after style load / basemap swaps (imperative image source).
  useEffect(() => {
    if (!cropAiMapOverlay || !isMapStyleReady) return;
    const map = mapRef.current?.getMap?.() ?? mapRef.current;
    if (!map) return;
    siImperativeCustomLayerSourceIdsRef.current.add(CROP_AI_PREDICTION_SOURCE_ID);
    const sync = () => {
      syncCropAiPredictionOnMapbox(map, cropAiMapOverlayRef.current);
    };
    sync();
    let raf = 0;
    let attempts = 0;
    const tick = () => {
      sync();
      attempts += 1;
      if (attempts < 20) raf = window.requestAnimationFrame(tick);
    };
    raf = window.requestAnimationFrame(tick);
    const onStyle = () => sync();
    try {
      map.on?.('idle', onStyle);
      map.on?.('styledata', onStyle);
    } catch {
      /* ignore */
    }
    return () => {
      window.cancelAnimationFrame(raf);
      try {
        map.off?.('idle', onStyle);
        map.off?.('styledata', onStyle);
      } catch {
        /* ignore */
      }
    };
  }, [cropAiMapOverlay, isMapStyleReady]);

